// Admin.js
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Admin.css';
import Sidebar from './Sidebar'; // Sidebar importu
import PageTitle from '../PageTitle';

function Admin() {
  const navigate = useNavigate();
  const [adminName, setAdminName] = useState('');
/*
useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/giris-yap'); // Eğer token yoksa login sayfasına yönlendir
    } else {
      // Eğer token varsa, adminin ismini al
      const userInfo = JSON.parse(atob(token.split('.')[1])); // JWT'deki payload kısmını çöz
      setAdminName(userInfo.name); // Admin ismini state'e kaydet
    }
  }, [navigate]);
*/ 
  

  return (
    <>
      <PageTitle title="Dashboard" />
      <div className="admin-panel">
        <Sidebar />
        <main className="main-content">
          <div className="welcome-message">
            <h1>Hoşgeldiniz, {adminName}!</h1> {/* Adminin ismi burada gösterilecek */}
          </div>
          <div className="stats-container">
            <div className="stat-box">
              <h3>Toplam Ürün</h3>
              <p>0</p>
            </div>
            <div className="stat-box">
              <h3>Toplam İleti</h3>
              <p>0</p>
            </div>
          </div>
        </main>
      </div>
    </>
  );
}

export default Admin;
